lect pooja address", context);        return;      }    }    else    {      if(addressController.text.toString() == "Select Address")      {        showToast("Please select pooja ", context);        return ;      }    }    if(pujaId.isEmpty)    {      showToast("Please select pooja",context);      return;    }     if(selectPujaController.text.isEmpty)    {      showToast("Please select pooja",context);      return;    }     if(leaveDetailController.text.isEmpty)    {      if(selectedDate.toString()==("Pick Date"))      {        showToast("Select date for pooja ",context);        return;      }      if(selectedTime.toString()==("Pick Time"))      {        showToast("Select time for pooja ",context);        return;      }    }      _reviewBookingDialog();  }  bookPujaRequest() async {    setState(() {      _isLoading = true;    });    Navigator.pop(context);        final url = Uri.parse(MAIN_URL + bookPuja);/*    @Field("user_id") user_id: String,    @Field("puja_id") puja_id: String,    @Field("booking_date") booking_date: String,    @Field("booking_address") booking_address: String,    @Field("auspicious_description") auspicious_description: String,    @Field("pickup_by_user") pickup_by_user: String,    @Field("puja_goods_provide_by_user") puja_goods_provide_by_user: String,*/    Map<String, String> jsonBody = {      'user_id' : sessionManager.getUserId().toString(),      'email' : sessionManager.getEmail().toString(),      'puja_id' : pujaId,      'booking_date' : dateTimeForPass,      'booking_address' : addressController.text,      'auspicious_description' : leaveDetailController.text,      'pickup_by_user' : isPickupPriest ? "1" : "0",      'puja_goods_provide_by_user' : isWantGoods ? "1" : "0",    };    final response = await http.post(url, body: jsonBody);    final statusCode = response.statusCode;    final body = response.body;    Map<String, dynamic> user = jsonDecode(body);    var da