borderRadius: BorderRadius.circular(14.0),                                borderSide: const BorderSide(                                    width: 0, style: BorderStyle.none)),                            filled: true,                            hintText: "Search",                            hintStyle: const TextStyle(                              color: text_dark,                              fontSize: 14,                              fontWeight: FontWeight.w900,                            ),                          ),                        ),                      ),                      Expanded(                        child: ListView.builder(                            shrinkWrap: true,                            physics: const ScrollPhysics(),                            scrollDirection: Axis.vertical,                            itemCount: listSearchCountryName.isNotEmpty ? listSearchCountryName.length : listCountryCode.length,                            itemBuilder: (BuildContext context, int i) {                              return InkWell(                                onTap: (){                                  setState((){                                    countryCode = listSearchCountryName.isNotEmpty ? listSearchCountryName[i].dialCode : listCountryCode[i].dialCode;                                  });                                  Navigator.pop(context);                                },                                child: Container(                                  margin: const EdgeInsets.only(left: 14, right: 14),                                  child: Column(                                    children: [                                      Padding(                                        padding: const EdgeInsets.all(16),                                        child: Row(                                          mainAxisAlignment: MainAxisAlignment.spaceBetween,                                          children: [                                            Flexible(child: Text( listSearchCountryName.isNotEmpty ? listSearchCountryName[i].name : listCountryCode[i].name.toString(),style: const TextStyle(fontSize: 14,fontWeight: FontWeight.w200,color: title), textAlign: TextAlign.start,)),                                            Text(listSearchCountryName.isNotEmpty ? listSearchCountryName[i].dialCode : listCountryCode[i].dialCode.toString(),style: const TextStyle(fontWeight: FontWeight.w300,color: text_new,fontSize: 16),)                                          ],                                        ),                                      ),                                      const Divider(height: 1,color: text_light,indent: 1,)                                    ],                                  ),                                ),                              );                            }                        ),                      )                    ],                  ),                );              }          );        });  }  List data = [];  Future<void> getCountryData() async {    var jsonText = await rootBundle.loadString('assets/countries.json');    setState(() => data = json.decode(jsonText));    var name = "";    var code = "";    var dialCode = "";    for (var i=0; i < data.length; i++)    {      name = data[i]['name'];      code = data[i]['code'];      dialCode = data[i]['dial_code'] != null ? data[i]['dial_code'] : "";      listCountryCode.add(CountryListResponseModel(name: name, dialCode: dialCode, code: code));    }  }  _showAlertDialog(String image, String text) {    Widget okButton = Image.asset(image,height: 160,width:160);    AlertDialog alert = AlertDialog(      content: Wrap(        children: [          Container(            width: MediaQuery.of(context).size.width,            margin: const EdgeInsets.only(left: 12,right: 12),            child: Column(              children: [                okButton,                Container(height: 12,),                Text(text,style: const TextStyle(fontSize: 18,color: text_new,fontWeight: FontWeight.w900),textAlign: TextAlign.center),              ],            ),          ),        ],      ),    );    showDialog(      context: context,      barrierDismissible: false,      builder: (BuildContext context) {        return alert;      },    );    Timer(const Duration(seconds: 3), () {      Navigator.pop(context);    },);  }  _setDatePicker(TextEditingController controller){    showCupertinoModalPopup(        context: context,        builder: (BuildContext builder) {          return Container(            height: MediaQuery.of(context).copyWith().size.height*0.25,            color: Colors.white,            child: CupertinoDatePicker(              mode: CupertinoDatePickerMode.date,              onDateTimeChanged: (value) {                if (value != selectedDate) {                  setState(()                  {                    String formattedDate = DateFormat('MMMM dd, yyyy').format(value);                    controller.text = formattedDate;                  });                }              },              initialDateTime: DateTime.now(),              minimumYear: 1900,              maximumYear: int.parse(getCurrentYear()),            ),          );        }    );  }  _setPickDate(TextEditingController controller, StateSetter setState){    showCupertinoModalPopup(        context: context,        builder: (BuildContext builder) {          return Container(            height: MediaQuery.of(context).copyWith().size.height*0.25,            color: Colors.white,            child: CupertinoDatePicker(              mode: CupertinoDatePickerMode.date,              onDateTimeChanged: (value) {                if (value != null && value != selectedDate) {                  setState(()                  {                    String formattedDate = DateFormat('MMM dd, yyyy').format(value);                    // controller.text = formattedDate;                    selectedDate = formattedDate;                  });                }              },              initialDateTime: DateTime.now(),              minimumYear: 2023,              maximumYear: 2035,            ),          );        }    );  }  _setTimePicker(TextEditingController controller, StateSetter setState){    showCupertinoModalPopup(        context: context,        builder: (BuildContext builder) {          return Container(            height: MediaQuery.of(context).copyWith().size.height*0.25,            color: Colors.white,            child: CupertinoDatePicker(              mode: CupertinoDatePickerMode.time,              onDateTimeChanged: (value) {                if (value != null && value != selectedTime) {                  setState(() {                    selectedTime = ("${value.hour}:${value.minute}${value.timeZoneName}").toString();                    selectedTime = DateFormat("h:mm a").format(value);                    print(selectedTime);                    controller.text =  DateFormat("h:mm a").format(value);                  });                }              },              initialDateTime: DateTime.now(),              use24hFormat: false,            ),          );        }    );  }   getTempleList() async {    var location = "$lat,$long";    print("Test$location");    Map<String, dynamic> jsonBody = {      'location': location,      'rankby': "distance",      'keyword': "hindu temple",      'key': API_KEY,    };    var uri = Uri.https('maps.googleapis.com', '/maps/api/place/nearbysearch/json', jsonBody);    var response = await http.get(uri, headers: {      HttpHeaders.contentTypeHeader: 'application/json',    });    final statusCode = response.statusCode;    final body = response.body;    Map<String, dynamic> user = jsonDecode(body);    var dataResponse = TempleListResponseModel.fromJson(user);    if (statusCode == 200)    {      _listTemples = [];      _listTemples = dataResponse.results ?? [];      setState(() {        _isLoading = false;      });    }    else    {      setState(() {        _isLoading = false;      });    }  }  getPrices() async {    final url = Uri.parse(WEBSITE_URL + priceJson);    final response = await http.get(url);    final statusCode = response.statusCode;    final body = response.body;    Map<String, dynamic> user = jsonDecode(body);    var dataResponse = PricesResponseModel.fromJson(user);    if (statusCode == 200)      {        matchMakingPrice = dataResponse.matchmakingPrice.toString();        astroPrice = dataResponse.astrologyPrice.toString();        rashiPrice = dataResponse.rashiPrice.toString();      }  }}